 auto foreign=pAccepted;for(auto&t:foreign)t.field=8;assert(resolveCapCoverage(bPatches,foreign,again,repeat));assert(sameMesh(again,bCaps));for(auto&t:foreign){t.field=7;t.face+=40;}assert(resolveCapCoverage(bPatches,foreign,again,repeat));assert(sameMesh(again,bCaps));
 auto bad=pAccepted;bool changed=false;for(auto&t:bad)if(t.face==10){t.positions[0][1]+=1;changed=true;break;}assert(changed);auto priorMesh=again;auto priorAccepted=repeat;assert(!resolveCapCoverage(bPatches,bad,again,repeat));assert(sameMesh(again,priorMesh));assert(repeat.size()==priorAccepted.size()&&std::memcmp(repeat.data(),priorAccepted.data(),repeat.size()*sizeof(CapTriangle))==0);
 const float angle=.645771823f,cs=std::cos(angle),sn=std::sin(angle),scale=2;const Vec3 translation{300,17,-400};const auto local=[&](Vec3 p){p=p-translation;return Vec3{(cs*p.x-sn*p.z)/scale,p.y/scale,(sn*p.x+cs*p.z)/scale};};const auto world=[&](Vec3 p){return Vec3{scale*(cs*p.x+sn*p.z)+translation.x,scale*p.y+translation.y,scale*(-sn*p.x+cs*p.z)+translation.z};};
 auto rotated=bed;for(auto&o:rotated)for(auto&t:o.second)for(auto&v:t){v.position=local(v.position);auto n=v.normal;v.normal={cs*n.x-sn*n.z,n.y,sn*n.x+cs*n.z};}
 Cut derived=c;derived.center=local(c.center);derived.radius/=scale;derived.axes={Vec3{cs,0,sn},Vec3{0,1,0},Vec3{-sn,0,cs}};assert(valid(derived));auto fieldChange=derived;fieldChange.field=8;assert(equal(derived,fieldChange));assert(!equal(c,derived));auto invalid=derived;invalid.axes[1]={0,2,0};assert(!valid(invalid));
 std::vector<CapPatch>rotatedPatches;Mesh rResult,rOuter,rCaps;assert(reconstructWorld(rotated,{0,1,2},{derived},rResult,&rOuter,&rCaps,&rotatedPatches));auto earlierLocal=pAccepted;for(auto&t:earlierLocal)for(auto&p:t.positions){auto v=local({p[0],p[1],p[2]});p={v.x,v.y,v.z};}std::vector<CapTriangle>rotatedAccepted;assert(resolveCapCoverage(rotatedPatches,earlierLocal,again,rotatedAccepted));for(auto&t:rotatedAccepted)for(auto&p:t.positions){auto v=world({p[0],p[1],p[2]});p={v.x,v.y,v.z};}
 std::cout<<"rotated37_scaled2_translated_remaining="<<area(rotatedAccepted)<<" floor="<<area(floor(rotatedAccepted))<<std::endl;assert(std::abs(area(rotatedAccepted)-area(bAccepted))<.5);assert(area(floor(rotatedAccepted))<.05);
 Mesh combined=bOuter;storm_ship_laser::appendMesh(combined,bResolved);const double primaryFloor=ray(pResult,{-1577,1000,1009},{-1577,-1500,1009});assert(std::abs(primaryFloor-.488)<1.e-6);assert(ray(combined,{-1577,1000,1009},{-1577,-1500,1009})==2);
